"use client"

import { Info, Minus, Plus, RotateCcw, X } from "lucide-react"

import { Badge } from "@/registry/new-york/ui/badge"
import { Button } from "@/registry/new-york/ui/button"
import { Card, CardContent } from "@/registry/new-york/ui/card"

import {
  algeriaWilayas,
  type AlgeriaWilaya,
} from "../data/algeria-wilayas"

import MapGuideDialog from "./map-guide-dialog"

import {
  BOTTOM_OVERLAY_SPACE,
  type WilayaStatus,
} from "../utils/vigilance-map.utils"

import { useVigilanceMap } from "../hooks/use-vigilance-map"

type VigilanceMapProps = {
  data?: AlgeriaWilaya[]
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
  wilayaColors?: Partial<Record<string, string>>
  defaultColor?: string
  strokeColor?: string
  height?: number
  selectable?: boolean
  selectedWilayas?: string[]
  onWilayaClick?: (wilaya: AlgeriaWilaya) => void
  onSelectionChange?: (selectedIds: string[]) => void
}

export function VigilanceMap({
  data = algeriaWilayas,
  wilayaStatuses,
  wilayaColors,
  defaultColor = "#22c55e",
  strokeColor = "#ffffff",
  height = 560,
  selectable = true,
  selectedWilayas,
  onWilayaClick,
  onSelectionChange,
}: VigilanceMapProps) {
  const {
    mapContainerRef,
    svgRef,
    selected,
    transform,
    isGuideOpen,
    setIsGuideOpen,
    setIsPointerInside,
    selectedWilayaObjects,
    getWilayaFill,
    toggleWilaya,
    removeWilaya,
    zoomIn,
    zoomOut,
    resetTransform,
  } = useVigilanceMap({
    data,
    wilayaStatuses,
    wilayaColors,
    defaultColor,
    selectable,
    selectedWilayas,
    onWilayaClick,
    onSelectionChange,
  })

  return (
    <Card className="relative h-full overflow-hidden py-1">
      <CardContent className="relative h-full p-0">
        <div
          ref={mapContainerRef}
          className="relative h-full w-full overflow-hidden bg-muted/20"
          style={{
            minHeight: height,
            paddingBottom: BOTTOM_OVERLAY_SPACE,
          }}
          onMouseEnter={() => setIsPointerInside(true)}
          onMouseLeave={() => setIsPointerInside(false)}
        >
          <div className="absolute right-3 top-3 z-10 flex items-center gap-2 rounded-lg border bg-background/90 p-2 shadow-sm backdrop-blur">
            <Button
              type="button"
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={zoomOut}
              aria-label="Zoom out"
            >
              <Minus className="h-4 w-4" />
            </Button>

            <Button
              type="button"
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={zoomIn}
              aria-label="Zoom in"
            >
              <Plus className="h-4 w-4" />
            </Button>

            <Button
              type="button"
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={resetTransform}
              aria-label="Reset map"
            >
              <RotateCcw className="h-4 w-4" />
            </Button>

            <Button
              type="button"
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => setIsGuideOpen(true)}
              aria-label="Open map guide"
            >
              <Info className="h-4 w-4" />
            </Button>
          </div>

          <svg
            ref={svgRef}
            viewBox="0 0 1000 1000"
            className="h-full min-h-[420px] w-full select-none"
            role="img"
            aria-label="Carte interactive des wilayas d'Algérie"
          >
            <g
              transform={`translate(${transform.x} ${transform.y}) scale(${transform.scale})`}
            >
              {data.map((wilaya) => {
                const id = String(wilaya.id)
                const isSelected = selected.includes(id)
                const isInteractive = selectable || Boolean(onWilayaClick)

                return (
                  <path
                    key={id}
                    d={wilaya.d}
                    fill={getWilayaFill(id)}
                    stroke={isSelected ? "#374151" : strokeColor}
                    strokeWidth={
                      isSelected
                        ? 1.8 / transform.scale
                        : 0.8 / transform.scale
                    }
                    className={[
                      "outline-none transition-opacity duration-200",
                      isInteractive
                        ? "cursor-pointer hover:opacity-80 focus:opacity-80"
                        : "",
                    ].join(" ")}
                    onClick={(event) => {
                      event.stopPropagation()
                      toggleWilaya(wilaya, event.altKey)
                    }}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault()
                        toggleWilaya(wilaya, event.altKey)
                      }
                    }}
                    tabIndex={isInteractive ? 0 : -1}
                    role={isInteractive ? "button" : undefined}
                    aria-label={wilaya.name}
                    aria-pressed={
                      selectable ? isSelected : undefined
                    }
                  >
                    <title>{wilaya.name}</title>
                  </path>
                )
              })}
            </g>
          </svg>

          <div className="absolute inset-x-0 bottom-0 z-20 border-t bg-background/95 px-4 py-3 backdrop-blur supports-[backdrop-filter]:bg-background/80">
            <div className="flex flex-wrap items-center gap-2">
              {selectedWilayaObjects.length === 0 ? (
                <span className="text-sm text-muted-foreground">
                  No wilaya selected
                </span>
              ) : (
                selectedWilayaObjects.map((wilaya) => (
                  <Badge
                    key={wilaya.id}
                    variant="secondary"
                    className="flex items-center gap-2 rounded-full px-3 py-1"
                  >
                    <span>{wilaya.name}</span>

                    <button
                      type="button"
                      className="rounded-full p-0.5 hover:bg-black/10 dark:hover:bg-white/10"
                      onClick={() => removeWilaya(String(wilaya.id))}
                      aria-label={`Remove ${wilaya.name}`}
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </Badge>
                ))
              )}
            </div>
          </div>
        </div>
      </CardContent>

      <MapGuideDialog
        isGuideOpen={isGuideOpen}
        setIsGuideOpen={setIsGuideOpen}
      />
    </Card>
  )
}

export default VigilanceMap

"use client"

import * as React from "react"
import type { AlgeriaWilaya } from "../data/algeria-wilayas"
import {
  MIN_SCALE,
  MAX_SCALE,
  ZOOM_STEP,
  PAN_STEP,
  getNextSelectedWilayas,
  getSelectedWilayaObjects,
  getWilayaFillColor,
  type WilayaStatus,
} from "../utils/vigilance-map.utils"

type UseVigilanceMapParams = {
  data: AlgeriaWilaya[]
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
  wilayaColors?: Partial<Record<string, string>>
  defaultColor: string
  selectable: boolean
  selectedWilayas?: string[]
  onWilayaClick?: (wilaya: AlgeriaWilaya) => void
  onSelectionChange?: (selectedIds: string[]) => void
}

export function useVigilanceMap({
  data,
  wilayaStatuses,
  wilayaColors,
  defaultColor,
  selectable,
  selectedWilayas,
  onWilayaClick,
  onSelectionChange,
}: UseVigilanceMapParams) {
  const [internalSelected, setInternalSelected] = React.useState<string[]>([])
  const [isPointerInside, setIsPointerInside] = React.useState(false)
  const [isGuideOpen, setIsGuideOpen] = React.useState(false)
  const [transform, setTransform] = React.useState({
    scale: 1,
    x: 0,
    y: 0,
  })

  const mapContainerRef = React.useRef<HTMLDivElement | null>(null)
  const svgRef = React.useRef<SVGSVGElement | null>(null)

  const selected = selectedWilayas ?? internalSelected

  const updateSelection = React.useCallback(
    (next: string[]) => {
      if (!selectedWilayas) {
        setInternalSelected(next)
      }
      onSelectionChange?.(next)
    },
    [selectedWilayas, onSelectionChange]
  )

  const toggleWilaya = React.useCallback(
    (wilaya: AlgeriaWilaya, multiSelect: boolean) => {
      const id = String(wilaya.id)

      const next = getNextSelectedWilayas({
        selected,
        wilayaId: id,
        selectable,
        multiSelect,
        wilayaStatuses,
      })

      if (selectable) {
        updateSelection(next)
      }

      onWilayaClick?.(wilaya)
    },
    [selectable, selected, updateSelection, onWilayaClick, wilayaStatuses]
  )

  const removeWilaya = React.useCallback(
    (id: string) => {
      updateSelection(selected.filter((item) => item !== id))
    },
    [selected, updateSelection]
  )

  const selectedWilayaObjects = React.useMemo(() => {
    return getSelectedWilayaObjects(data, selected)
  }, [data, selected])

  const getWilayaFill = React.useCallback(
    (wilayaId: string) =>
      getWilayaFillColor({
        wilayaId,
        selected,
        wilayaColors,
        wilayaStatuses,
        defaultColor,
      }),
    [selected, wilayaColors, wilayaStatuses, defaultColor]
  )

  const getSvgPoint = React.useCallback((clientX: number, clientY: number) => {
    const svg = svgRef.current
    if (!svg) return null

    const point = svg.createSVGPoint()
    point.x = clientX
    point.y = clientY

    const ctm = svg.getScreenCTM()
    if (!ctm) return null

    return point.matrixTransform(ctm.inverse())
  }, [])

  const zoomAtPoint = React.useCallback(
    (clientX: number, clientY: number, nextScale: number) => {
      const svgPoint = getSvgPoint(clientX, clientY)
      if (!svgPoint) return

      setTransform((prev) => {
        const clampedScale = Math.min(MAX_SCALE, Math.max(MIN_SCALE, nextScale))
        if (clampedScale === prev.scale) return prev

        const worldX = (svgPoint.x - prev.x) / prev.scale
        const worldY = (svgPoint.y - prev.y) / prev.scale

        return {
          scale: clampedScale,
          x: svgPoint.x - worldX * clampedScale,
          y: svgPoint.y - worldY * clampedScale,
        }
      })
    },
    [getSvgPoint]
  )

  const zoomIn = React.useCallback(() => {
    const wrapper = mapContainerRef.current
    if (!wrapper) return

    const rect = wrapper.getBoundingClientRect()
    zoomAtPoint(
      rect.left + rect.width / 2,
      rect.top + rect.height / 2,
      transform.scale + 0.3
    )
  }, [transform.scale, zoomAtPoint])

  const zoomOut = React.useCallback(() => {
    const wrapper = mapContainerRef.current
    if (!wrapper) return

    const rect = wrapper.getBoundingClientRect()
    zoomAtPoint(
      rect.left + rect.width / 2,
      rect.top + rect.height / 2,
      transform.scale - 0.3
    )
  }, [transform.scale, zoomAtPoint])

  const resetTransform = React.useCallback(() => {
    setTransform({
      scale: 1,
      x: 0,
      y: 0,
    })
  }, [])

  React.useEffect(() => {
    const wrapper = mapContainerRef.current
    if (!wrapper) return

    const handleWheel = (e: WheelEvent) => {
      if (!isPointerInside) return

      e.preventDefault()
      e.stopPropagation()

      if (e.ctrlKey) {
        const direction = e.deltaY > 0 ? -1 : 1
        zoomAtPoint(e.clientX, e.clientY, transform.scale + direction * ZOOM_STEP)
        return
      }

      setTransform((prev) => {
        const horizontalDelta = e.shiftKey
          ? (e.deltaY !== 0 ? e.deltaY : e.deltaX)
          : e.deltaX

        return {
          ...prev,
          x: prev.x - horizontalDelta * PAN_STEP,
          y: e.shiftKey ? prev.y : prev.y - e.deltaY * PAN_STEP,
        }
      })
    }

    wrapper.addEventListener("wheel", handleWheel, { passive: false })

    return () => {
      wrapper.removeEventListener("wheel", handleWheel)
    }
  }, [isPointerInside, transform.scale, zoomAtPoint])

  return {
    mapContainerRef,
    svgRef,
    selected,
    transform,
    isGuideOpen,
    setIsGuideOpen,
    setIsPointerInside,
    selectedWilayaObjects,
    getWilayaFill,
    toggleWilaya,
    removeWilaya,
    zoomIn,
    zoomOut,
    resetTransform,
  }
}

import type { AlgeriaWilaya } from "../data/algeria-wilayas"

export type WilayaStatus = "green" | "yellow" | "orange" | "red"

export const STATUS_COLORS: Record<WilayaStatus, string> = {
  green: "#22c55e",
  yellow: "#eab308",
  orange: "#f97316",
  red: "#ef4444",
}

export const SELECTED_COLOR = "#9ca3af"
export const MIN_SCALE = 1
export const MAX_SCALE = 6
export const ZOOM_STEP = 0.5
export const PAN_STEP = 1
export const BOTTOM_OVERLAY_SPACE = 116

export function getWilayaStatus(
  wilayaId: string,
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
): WilayaStatus {
  return wilayaStatuses?.[wilayaId] ?? "green"
}

export function areAllSelectedWilayasGreen(
  selected: string[],
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
) {
  return selected.every((selectedId) => {
    return getWilayaStatus(selectedId, wilayaStatuses) === "green"
  })
}

export function canMultiSelectWilaya(
  wilayaId: string,
  selected: string[],
  multiSelect: boolean,
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
) {
  return (
    multiSelect &&
    getWilayaStatus(wilayaId, wilayaStatuses) === "green" &&
    areAllSelectedWilayasGreen(selected, wilayaStatuses)
  )
}

export function getWilayaFillColor({
  wilayaId,
  selected,
  wilayaColors,
  wilayaStatuses,
  defaultColor,
}: {
  wilayaId: string
  selected: string[]
  wilayaColors?: Partial<Record<string, string>>
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
  defaultColor: string
}) {
  if (selected.includes(wilayaId)) return SELECTED_COLOR
  if (wilayaColors?.[wilayaId]) return wilayaColors[wilayaId]

  const status = wilayaStatuses?.[wilayaId]
  if (status) return STATUS_COLORS[status]

  return defaultColor
}

export function getSelectedWilayaObjects(
  data: AlgeriaWilaya[],
  selected: string[]
) {
  return data.filter((wilaya) => selected.includes(String(wilaya.id)))
}

export function getNextSelectedWilayas({
  selected,
  wilayaId,
  selectable,
  multiSelect,
  wilayaStatuses,
}: {
  selected: string[]
  wilayaId: string
  selectable: boolean
  multiSelect: boolean
  wilayaStatuses?: Partial<Record<string, WilayaStatus>>
}) {
  if (!selectable) return selected

  const canMultiSelect = canMultiSelectWilaya(
    wilayaId,
    selected,
    multiSelect,
    wilayaStatuses
  )

  if (canMultiSelect) {
    return selected.includes(wilayaId)
      ? selected.filter((item) => item !== wilayaId)
      : [...selected, wilayaId]
  }

  return selected.length === 1 && selected[0] === wilayaId ? [] : [wilayaId]
}
